#pragma once

/* Base version of the WebKit Autoloader (WKAL) content.
 * Bump this when the autoloader frontend changes — it triggers the app-cache
 * update and also marks the matching WKALI installer build. */
#define WKAL_VERSION "0.5.2"

/* Full build version (stable: <base>, dev: <base>-dev-<hash|timestamp>),
 * generated by tools/gen_version.py — see include/wkali_version.h */
#include "wkali_version.h"

/* --- Coexistence -------------------------------------------------------
 *
 * Both builds must be installable on one console at the same time:
 *
 *   upstream PLK    WKAL00001  "WebKit Autoloader"  127.0.0.1:18181
 *   this fork       WKLX00001  "Jailbreak"          127.0.0.1:18282
 *
 * The port is part of the page's origin, and AppCache is keyed by origin, so
 * it MUST differ from upstream's 18181. Sharing the port would mean sharing
 * one cache entry: whichever app was launched last would overwrite the other's
 * cached autoloader. The title ID must differ for the same reason at the app
 * level — same ID means one app overwrites the other.
 * ---------------------------------------------------------------------- */
#define WKALI_PORT 18282

/* Title ID and homescreen label of the installed app.
 *
 * WKAL_TITLE_ID must match "titleId" in assets/param.json.template —
 * app_installer.c builds /user/app/<title_id>/... from this constant while the
 * metadata comes from the template, whose deeplink gen_version.py keeps in sync
 * with WKALI_PORT. */
#define WKAL_TITLE_ID     "WKLX00001"
#define WKAL_APP_LABEL    "Jailbreak"

/* Process identity — used to kill stale installer instances on startup */
#define WKALI_THREAD_NAME "wkali.elf"

/* Routes */
#define ROUTE_INDEX "/"
#define ROUTE_INDEX_HTML "/index.html"
#define ROUTE_CACHE_MANIFEST "/cache.appcache"
#define ROUTE_INSTALL "/install"
#define ROUTE_VERSION "/version"
#define ROUTE_CLEAR_WEBKIT_DATA "/clear-webkit-data"
#define ROUTE_EXIT "/exit"

/* Logging (implementation in log.c) */
void wkali_log(const char *fmt, ...);
size_t wkali_wait_logs(size_t *pos, char *out_buf, size_t max_len);
void wkali_log_wakeup(void);

/* Notifications (declared in notification.h) */
#include "notification.h"
